# ECharts: Tufte Configuration

Load this file when generating any ECharts chart code.

## Tufte theme registration

Register once at app initialization:

```typescript
import * as echarts from 'echarts';

const tufteTheme = {
  color: ['#666666', '#4e79a7', '#f28e2b', '#e15759', '#76b7b2'],
  backgroundColor: '#fffff8',
  textStyle: {
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111',
  },
  title: {
    textStyle: {
      fontSize: 18,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    subtextStyle: {
      fontSize: 13,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
  },
  line: {
    itemStyle: { borderWidth: 0 },
    lineStyle: { width: 1.5 },
    symbolSize: 0,
    symbol: 'circle',
    smooth: false,
  },
  bar: {
    itemStyle: {
      barBorderWidth: 0,
      barBorderColor: '#ccc',
    },
  },
  categoryAxis: {
    axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, -apple-system, sans-serif',
    },
    splitLine: { show: false },
  },
  valueAxis: {
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, -apple-system, sans-serif',
    },
    splitLine: { show: false },
  },
  legend: { show: false },
  tooltip: {
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: {
      fontSize: 12,
      color: '#333',
      fontFamily: 'system-ui, sans-serif',
    },
    extraCssText: 'box-shadow: none;',
  },
  grid: {
    show: false,
    left: 60,
    right: 80,
    top: 60,
    bottom: 40,
    containLabel: false,
  },
};

echarts.registerTheme('tufte', tufteTheme);
```

Usage: `echarts.init(dom, 'tufte')`.

## Base option object

For inline use without theme registration:

```typescript
const tufteBaseOption: echarts.EChartsOption = {
  backgroundColor: '#fffff8',
  textStyle: {
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111',
  },
  grid: { show: false, left: 60, right: 80, top: 60, bottom: 40 },
  legend: { show: false },
  tooltip: {
    trigger: 'axis',
    backgroundColor: 'rgba(255,255,248,0.95)',
