arguments.content:
const echarts = require('echarts');
const fs = require('fs');

// Register Tufte theme
const tufteTheme = {
  color: ['#666666', '#4e79a7', '#f28e2b', '#e15759', '#76b7b2'],
  backgroundColor: '#fffff8',
  textStyle: {
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111',
  },
  title: {
    textStyle: {
      fontSize: 18,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    subtextStyle: {
      fontSize: 13,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
  },
  line: {
    itemStyle: { borderWidth: 0 },
    lineStyle: { width: 1.5 },
    symbolSize: 0,
    symbol: 'circle',
    smooth: false,
  },
  bar: {
    itemStyle: {
      barBorderWidth: 0,
      barBorderColor: '#ccc',
    },
  },
  categoryAxis: {
    axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, -apple-system, sans-serif',
    },
    splitLine: { show: false },
  },
  valueAxis: {
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, -apple-system, sans-serif',
    },
    splitLine: { show: false },
  },
  legend: { show: false },
  tooltip: {
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: {
      fontSize: 12,
      color: '#333',
      fontFamily: 'system-ui, sans-serif',
    },
    extraCssText: 'box-shadow: none;',
  },
  grid: {
    show: false,
    left: 60,
    right: 80,
    top: 60,
    bottom: 40,
    containLabel: false,
  },
};

echarts.registerTheme('tufte', tufteTheme);

// Data
const stages = ['Production', 'Processing', 'Retail', 'Consumption'];
const regions = [
  'North America & Oceania',
  'Europe',
  'Sub-Saharan Africa',
  'South & Southeast Asia',
  'Latin America',
  'Global Average',
];

// waste_by_stage_and_region (percent of total waste at each stage per region)
const wasteData = {
  'North America & Oceania': { Production: 12.0, Processing: 8.5, Retail: 11.0, Consumption: 68.5 },
  'Europe': { Production: 14.0, Processing: 10.0, Retail: 12.5, Consumption: 63.5 },
  'Sub-Saharan Africa': { Production: 39.0, Processing: 28.0, Retail: 19.0, Consumption: 14.0 },
  'South & Southeast Asia': { Production: 32.0, Processing: 24.0, Retail: 18.0, Consumption: 26.0 },
  'Latin America': { Production: 28.0, Processing: 19.0, Retail: 17.0, Consumption: 36.0 },
  'Global Average': { Production: 24.0, Processing: 18.0, Retail: 15.0, Consumption: 43.0 },
};

// carbon_emissions_by_stage (global, percent of total emissions)
const carbonData = { Production: 30.5, Processing: 22.0, Retail: 16.5, Consumption: 31.0 };

// avoidable_waste_by_stage (percent avoidable at each stage, Global Average)
const avoidableData = {
  'North America & Oceania': { Production: 55, Processing: 70, Retail: 78, Consumption: 62 },
  'Europe': { Production: 58, Processing: 72, Retail: 80, Consumption: 65 },
  'Sub-Saharan Africa': { Production: 75, Processing: 68, Retail: 50, Consumption: 30 },
  'South & Southeast Asia': { Production: 72, Processing: 65, Retail: 52, Consumption: 40 },
  'Latin America': { Production: 68, Processing: 60, Retail: 58, Consumption: 48 },
  'Global Average': { Production: 65, Processing: 67, Retail: 64, Consumption: 52 },
};

// Stage colors (sequential, muted)
const stageColors = {
  'Production': '#4e79a7',
  'Processing': '#f28e2b',
  'Retail': '#e15759',
  'Consumption': '#76b7b2',
};

// Build the stacked bar data: each region = one bar with 4 segments
// ECharts stacked bar: each series = one stage, regions as categories
const stackData = {};
stages.forEach(stage => {
  stackData[stage] = regions.map(r => wasteData[r][stage]);
});

// Build annotation data for Global Average avoidable %
const avoidableAnnotations = regions.map(r => ({
  stage: r,
  annotations: stages.map(s => avoidableData[r][s]),
}));

// Carbon emission line (percent scale, aligned with waste %)
// We'll plot it as a line series over the bar chart

// Chart dimensions
const chartWidth = 1100;
const chartHeight = 620;

// Create chart
const chart = echarts.init(null, 'tufte', { width: chartWidth, height: chartHeight });
const option = {
  backgroundColor: '#fffff8',

  title: {
    text: 'Food Waste Distribution Across the Supply Chain',
    subtext: 'Shares by stage and region · Globally, 30.5% of food-waste emissions come from production and 31.0% from consumption, yet waste concentrates at consumption in high-income regions and production in low-income ones',
    left: 10,
    top: 8,
    textStyle: {
      fontSize: 20,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    subtextStyle: {
      fontSize: 12,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
  },

  grid: {
    show: false,
    left: 175,
    right: 110,
    top: 90,
    bottom: 55,
    containLabel: false,
  },

  tooltip: {
    trigger: 'axis',
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: {
      fontSize: 12,
      color: '#333',
      fontFamily: 'system-ui, sans-serif',
    },
    extraCssText: 'box-shadow: none;',
    formatter: function(params) {
      if (!params || params.length === 0) return '';
      const region = params[0].name;
      let html = `<div style="font-family:'ET Book',Georgia,serif;font-size:12px;color:#111;">`;
      html += `<strong>${region}</strong><br/>`;
      let total = 0;
      params.forEach(p => {
        if (p.seriesType === 'bar') {
          total += p.value;
          html += `<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${p.color};margin-right:5px;"></span>${p.seriesName}: ${p.value}%<br/>`;
        }
      });
      html += `<strong>Total: ${total}%</strong>`;
      // Show avoidable %
      const avoid = avoidableData[region];
      if (avoid) {
        html += `<br/><span style="color:#888;font-size:11px;">Avoidable: Prod ${avoid.Production}% · Proc ${avoid.Processing}% · Ret ${avoid.Retail}% · Cons ${avoid.Consumption}%</span>`;
      }
      html += `</div>`;
      return html;
    },
  },

  legend: {
    show: false,
  },

  xAxis: {
    type: 'category',
    data: regions,
    position: 'bottom',
    axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
    axisTick: { show: false },
    axisLabel: {
      color: '#111',
      fontSize: 11,
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
      rotate: 0,
      interval: 0,
    },
    splitLine: { show: false },
    boundaryGap: true,
  },

  yAxis: {
    type: 'value',
    max: 100,
    min: 0,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, sans-serif',
      formatter: '{value}%',
    },
    splitLine: { show: false },
  },

  // Stacked bars for each stage
  series: stages.map((stage, si) => ({
    name: stage,
    type: 'bar',
    stack: 'waste',
    data: regions.map(r => wasteData[r][stage]),
    itemStyle: {
      color: stageColors[stage],
      barBorderWidth: 0,
    },
    barWidth: 28,
    label: {
      show: false,
    },
    tooltip: {
      show: true,
    },
    z: 10 - si,
  })),

  // Carbon emission line overlaid on top
  series.concat([{
    name: 'Carbon Emissions',
    type: 'line',
    data: stages.map(s => carbonData[s]),
    symbol: 'circle',
    symbolSize: 6,
    lineStyle: {
      color: '#111',
      width: 2,
      type: 'solid',
    },
    itemStyle: {
      color: '#111',
      borderWidth: 0,
    },
    endLabel: {
      show: true,
      formatter: 'Carbon: {c}%',
      fontSize: 12,
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
      color: '#111',
    },
    z: 20,
    tooltip: {
      show: true,
      formatter: 'Carbon emissions: {c}% of total',
    },
    markPoint: {
      data: [
        { type: 'max', name: 'Max Carbon' },
      ],
      symbol: 'circle',
      symbolSize: 5,
      label: {
        show: true,
        position: 'top',
        formatter: 'Peak: {c}%',
        fontSize: 11,
        fontStyle: 'italic',
        color: '#111',
        fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
      },
      itemStyle: { color: '#111' },
    },
  }]),
};

// Fix: correctly concat series
const fullOption = {
  ...option,
  series: [
    ...stages.map((stage, si) => ({
      name: stage,
      type: 'bar',
      stack: 'waste',
      data: regions.map(r => wasteData[r][stage]),
      itemStyle: {
        color: stageColors[stage],
        barBorderWidth: 0,
      },
      barWidth: 28,
      label: {
        show: false,
      },
      z: 10 - si,
    })),
    {
      name: 'Carbon Emissions',
      type: 'line',
      xAxisIndex: 0,
      yAxisIndex: 0,
      data: stages.map(s => carbonData[s]),
      symbol: 'circle',
      symbolSize: 6,
      lineStyle: {
        color: '#111',
        width: 2,
