const echarts = require('echarts');
const fs = require('fs');

// Register Tufte theme
const tufteTheme = {
  color: ['#666666', '#4e79a7', '#f28e2b', '#e15759', '#76b7b2'],
  backgroundColor: '#fffff8',
  textStyle: {
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111',
  },
  title: {
    textStyle: {
      fontSize: 18,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    subtextStyle: {
      fontSize: 13,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
  },
  bar: {
    itemStyle: { barBorderWidth: 0, barBorderColor: '#ccc' },
  },
  categoryAxis: {
    axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
    axisTick: { show: false },
    axisLabel: { color: '#999', fontSize: 11, fontFamily: 'system-ui, sans-serif' },
    splitLine: { show: false },
  },
  valueAxis: {
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: { color: '#999', fontSize: 11, fontFamily: 'system-ui, sans-serif' },
    splitLine: { show: false },
  },
  legend: { show: false },
  tooltip: {
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: { fontSize: 12, color: '#333', fontFamily: 'system-ui, sans-serif' },
    extraCssText: 'box-shadow: none;',
  },
  grid: { show: false, left: 60, right: 80, top: 60, bottom: 40, containLabel: false },
};

echarts.registerTheme('tufte', tufteTheme);

// ---- Data ----
const stages = ['Production', 'Processing', 'Retail', 'Consumption'];
const regions = [
  'North America\n& Oceania',
  'Europe',
  'Sub-Saharan\nAfrica',
  'South & Southeast\nAsia',
  'Latin America',
  'Global\nAverage',
];

// waste_by_stage_and_region (% of total waste at each stage per region)
const wasteData = {
  'North America\n& Oceania': { Production: 12.0, Processing: 8.5, Retail: 11.0, Consumption: 68.5 },
  'Europe':                               { Production: 14.0, Processing: 10.0, Retail: 12.5, Consumption: 63.5 },
  'Sub-Saharan\nAfrica':                { Production: 39.0, Processing: 28.0, Retail: 19.0, Consumption: 14.0 },
  'South & Southeast\nAsia':            { Production: 32.0, Processing: 24.0, Retail: 18.0, Consumption: 26.0 },
  'Latin America':                      { Production: 28.0, Processing: 19.0, Retail: 17.0, Consumption: 36.0 },
  'Global\nAverage':                   { Production: 24.0, Processing: 18.0, Retail: 15.0, Consumption: 43.0 },
};

// carbon_emissions_by_stage (global, % of total emissions per stage)
const carbonData = { Production: 30.5, Processing: 22.0, Retail: 16.5, Consumption: 31.0 };
const carbonTotal = 4500; // Mt CO2e total
const carbonMt = { Production: 1372, Processing: 990, Retail: 742, Consumption: 1395 };

// avoidable_waste_by_stage (%, Global Average)
const avoidableData = {
  'North America\n& Oceania': { Production: 55, Processing: 70, Retail: 78, Consumption: 62 },
  'Europe':                               { Production: 58, Processing: 72, Retail: 80, Consumption: 65 },
  'Sub-Saharan\nAfrica':                { Production: 75, Processing: 68, Retail: 50, Consumption: 30 },
  'South & Southeast\nAsia':            { Production: 72, Processing: 65, Retail: 52, Consumption: 40 },
  'Latin America':                      { Production: 68, Processing: 60, Retail: 58, Consumption: 48 },
  'Global\nAverage':                   { Production: 65, Processing: 67, Retail: 64, Consumption: 52 },
};

// Stage colors
const stageColors = {
  'Production': '#4e79a7',
  'Processing': '#f28e2b',
  'Retail':     '#e15759',
  'Consumption':'#76b7b2',
};

// intervention impact
const interventionData = {
  Production: { food: 210, co2: 890 },
  Processing: { food: 155, co2: 665 },
  Retail:     { food: 120, co2: 475 },
  Consumption:{ food: 280, co2: 725 },
};

// ---- Chart: grouped stacked bars with carbon line overlay ----
// X-axis = stages; each stage has 5 region segments stacked; carbon line overlaid
// Regions as series groups, stacked
// Actually: better approach = stacked bars per region, grouped by stage
// ECharts: each series = one region, stack = stage (but we'd need 4 stacks...)
// Let's use: each region = one series (stacked by stage), xAxis = regions
// Then add carbon line with xAxisIndex to span all stages?

// Actually let's do:
// X-axis = stages (4 categories)
// For each stage, we show 5 region segments stacked + carbon % as line marker
// But ECharts stacked bar groups by series, not by x-axis value

// Strategy: stacked bars per region. X-axis = regions. Then overlay carbon as markers
// carbon line will be a separate series with data for each region... but carbon is per stage

// Better: X-axis = stages, 6 grouped bars (one per region) per stage, overlaid carbon line
// ECharts grouped bar: series = regions, data aligned to stages
// For grouped stacked bar... ECharts doesn't do both natively.
// So let's switch: horizontal stacked bar (regions as y-axis, stages stacked)
// Then carbon: plot a scatter/line at the right side showing carbon intensity per stage

// FINAL PLAN: Horizontal stacked bar chart
// Y-axis: 6 regions
// Each bar = stacked 4 segments (Production + Processing + Retail + Consumption = 100%)
// Carbon line: plotted at the bottom, aligned to stages (but we have 6 regions, not 4 stages)
// Carbon as a SECONDARY chart aligned below, or as annotation markers on right side

// Actually: put a slopegraph to the right showing carbon emissions by stage
// Left: horizontal stacked bars (regions by stage)
// Right: stage-wise carbon emissions with avoidable annotations

// Let's build it as: main chart = horizontal stacked bars
// Carbon data shown as a separate series overlay: for each region position, add carbon line dots
// showing the global carbon% per stage at the right edge... too complex

// SIMPLEST STRONG CHART:
// Horizontal stacked bars for regions
// X-axis = percentage (0-100, range frame)
// Y-axis = regions
// Each bar segmented into 4 stages with stage colors
// Add carbon% as line markers on right side of chart
// Add text annotations showing avoidable % for key stages

const chartWidth = 1100;
const chartHeight = 640;

const chart = echarts.init(null, 'tufte', { width: chartWidth, height: chartHeight });

const option = {
  backgroundColor: '#fffff8',

  title: {
    text: 'Where the World\'s Food Waste Goes — and What It Costs',
    subtext: 'Food waste share by supply chain stage · Regions sorted by consumption-heavy (top) to production-heavy (bottom) · Carbon line shows each stage\'s emissions burden',
    left: 10,
    top: 8,
    textStyle: {
      fontSize: 19,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    subtextStyle: {
      fontSize: 12,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
      lineHeight: 16,
    },
  },

  grid: {
    show: false,
    left: 170,
    right: 130,
    top: 95,
    bottom: 50,
    containLabel: false,
  },

  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'none' },
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: {
      fontSize: 12,
      color: '#333',
      fontFamily: 'system-ui, sans-serif',
    },
    extraCssText: 'box-shadow: none;',
    formatter: function(params) {
      if (!params || params.length === 0) return '';
      const region = params[0].name;
      let html = `<div style="font-family:'ET Book',Georgia,serif;font-size:12px;color:#111;">`;
      html += `<strong>${region.replace('\n', ' ')}</strong><br/>`;
      let total = 0;
      const stageMap = {};
      params.forEach(p => {
        if (p.seriesType === 'bar') {
          total += p.value;
          stageMap[p.seriesName] = p.value;
          const pct = p.value;
          html += `<span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${p.color};margin-right:5px;vertical-align:middle;"></span>${p.seriesName}: <strong>${pct}%</strong><br/>`;
        }
      });
      html += `<br/><strong>Total: ${total}%</strong>`;
      // Avoidable % annotation
      const avoid = avoidableData[region];
      if (avoid) {
        html += `<br/><span style="color:#888;font-size:11px;">Avoidable share → Prod ${avoid.Production}% · Proc ${avoid.Processing}% · Ret ${avoid.Retail}% · Cons ${avoid.Consumption}%</span>`;
      }
      html += `</div>`;
      return html;
    },
  },

  legend: {
    show: true,
    orient: 'horizontal',
    top: 85,
    right: 130,
    width: 400,
    itemWidth: 12,
    itemHeight: 12,
    itemGap: 16,
    textStyle: {
      fontSize: 11,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
  },

  xAxis: {
    type: 'value',
    min: 0,
    max: 100,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, sans-serif',
      formatter: '{value}%',
    },
    splitLine: { show: false },
  },

  yAxis: {
    type: 'category',
    data: regions,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#111',
      fontSize: 12,
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    splitLine: { show: false },
  },

  // Stacked bars for each stage (one series per stage = correct for Tufte stacked bar)
  series: stages.map((stage, si) => ({
    name: stage,
    type: 'bar',
    stack: 'waste',
    data: regions.map(r => wasteData[r][stage]),
    itemStyle: {
      color: stageColors[stage],
      barBorderWidth: 0,
      opacity: si === 0 ? 1 : 1,
    },
    barWidth: 32,
    label: {
      show: false,
    },
    z: 10 - si,
  })),

  // Carbon emission line as separate series, overlaid with markLine and markers
  // This series spans all regions (6 points), but we want to show it per-stage
  // So we use xAxisIndex to map to a hidden stage-based axis
};

const fullOption = {
  backgroundColor: '#fffff8',

  title: {
    text: 'Where the World\'s Food Waste Goes — and What It Costs',
    subtext: 'Stacked bars = waste share by stage within each region · Line = carbon emissions as % of global food-waste total · Sorted: consumption-heavy at top',
    left: 10,
    top: 8,
    textStyle: {
      fontSize: 19,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    subtextStyle: {
      fontSize: 12,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
      lineHeight: 16,
    },
  },

  grid: {
    show: false,
    left: 170,
    right: 130,
    top: 100,
    bottom: 50,
    containLabel: false,
  },

  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'none' },
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: {
      fontSize: 12,
      color: '#333',
      fontFamily: 'system-ui, sans-serif',
    },
    extraCssText: 'box-shadow: none;',
    formatter: function(params) {
      if (!params || params.length === 0) return '';
      const region = params[0].name;
      let html = `<div style="font-family:'ET Book',Georgia,serif;font-size:12px;color:#111;">`;
      html += `<strong>${region.replace('\n', ' ')}</strong><br/>`;
      let total = 0;
      params.forEach(p => {
        if (p.seriesType === 'bar') {
          total += p.value;
          const pct = p.value;
          html += `<span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${p.color};margin-right:5px;vertical-align:middle;"></span>${p.seriesName}: <strong>${pct}%</strong><br/>`;
        }
      });
      html += `<strong>Total: ${total}%</strong>`;
      const avoid = avoidableData[region];
      if (avoid) {
        html += `<br/><span style="color:#888;font-size:11px;">Avoidable → Prod ${avoid.Production}% · Proc ${avoid.Processing}% · Ret ${avoid.Retail}% · Cons ${avoid.Consumption}%</span>`;
      }
      html += `</div>`;
      return html;
    },
  },

  legend: {
    show: true,
    orient: 'horizontal',
    top: 88,
    right: 130,
    width: 380,
    itemWidth: 12,
    itemHeight: 12,
    itemGap: 14,
    textStyle: {
      fontSize: 11,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
  },

  xAxis: {
    type: 'value',
    min: 0,
    max: 100,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, sans-serif',
      formatter: '{value}%',
    },
    splitLine: { show: false },
  },

  yAxis: {
    type: 'category',
    data: regions,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: '#111',
      fontSize: 12,
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    },
    splitLine: { show: false },
  },

  series: [
    ...stages.map((stage, si) => ({
      name: stage,
      type: 'bar',
      stack: 'waste',
